  String errorsFor(List<int> indices, bool absolute) {
    final fields = <String>[];
    for (var m = 0; m < 7; m++) {
      final es = [for (final i in indices) errors[m][i]],
          metric = absolute ? mae(es) : rmse(es);
      fields.add('${methods[m]} ${real(metric)}');
    }
    return fields.join(' ');
  }
